DEFAULT_CHAPTERS = ["08", "09", "12", "14", "27", "30"]


def code_set_for(chapters: list[str]) -> frozenset[str]:
    """Return the union of exact NHI codes for the given chapter list."""
    result: set[str] = set()
    for ch in chapters:
        result.update(CHAPTER_CODES.get(ch, frozenset()))
    return frozenset(result)


def is_allergy_code(code: str) -> bool:
    """True when the code belongs to chapter 30 (allergy/immunology)."""
    return code in CHAPTER_CODES.get("30", frozenset())


